export const useUpdateLabelSchemaMutation = () => {
  const queryClient = useQueryClient();

  const { mutate, mutateAsync, isLoading, error } = useMutation<
    UpdateLabelSchemaResponse,
    Error,
    UpdateLabelSchemaParams
  >({
    mutationFn: async (params) => {
      // Sparse update: strip keys whose value is `undefined` so that they are
      // left untouched on the server. Keys with an empty string or a boolean
      // `false` value are intentional updates and must be forwarded as-is.
      const body = Object.fromEntries(
        Object.entries(params).filter(([, value]) => value !== undefined),
