/**
 * Renders a numeric label input (an HTML number input, role `spinbutton`).
 * The `min`/`max` HTML attributes reflect `input.min_value`/`input.max_value`
 * when they are provided. Clearing the field reports `null`; entering a number
 * reports the parsed numeric value.
 */
export const LabelSchemaInputNumeric = ({
  input,
  value,
  onChange,
  componentId,
  disabled,
}: LabelSchemaInputNumericProps) => {
  return (
    <Input
      componentId={componentId}
      type="number"
      disabled={disabled}
      value={value ?? ''}
      min={input.min_value ?? ''}
      max={input.max_value ?? ''}
      onChange={(event) => {
        const raw = event.target.value;
        if (raw === '') {
          onChange(null);
          return;
        }
        onChange(Number(raw));
      }}
    />
  );
};
