[metadata] {"type": "create", "filePath": "/workspace/repo/mlflow/server/js/src/experiment-tracking/components/label-schemas/widgets/LabelSchemaInputCategorical.tsx", "content": "import {
  DialogCombobox,
  DialogComboboxContent,
  DialogComboboxOptionList,
  DialogComboboxOptionListCheckboxItem,
  DialogComboboxOptionListSelectItem,
  DialogComboboxTrigger,
} from '@databricks/design-system';

export interface LabelSchemaInputCategoricalProps {
  input: {
    options: string[];
    multi_select?: boolean;
  };
  value: string | string[] | null | undefined;
  onChange: (value: string | string[]) => void;
  componentId: string;
  label: string;
  disabled?: boolean;
}

/**
 * Renders a categorical label input as a combobox accessible by the `label`
 * prop. When `multi_select` is falsy the control is single-select and reports
 * the chosen option string; when `multi_select` is true it is multi-select and
 * reports an array of the chosen options.
 */
export const LabelSchemaInputCategorical = ({
  input,
  value,
  onChange,
  componentId,
  label,
  disabled,
}: LabelSchemaInputCategoricalProps) => {
  const multiSelect = Boolean(input.multi_select);

  if (multiSelect) {
    const selected = Array.isArray(value) ? value : [];
    const toggle = (option: string) => {
      const next = selected.includes(option)
        ? selected.filter((item) => item !== option)
        : [...selected, option];
      onChange(next);
    };

    return (
      <DialogCombobox componentId={componentId} label={label} multiSelect value={selected}>
        <DialogComboboxTrigger allowClear={false} disabled={disabled} />
        <DialogComboboxContent>
          <DialogComboboxOptionList>
            {input.options.map((option) => (
              <DialogComboboxOptionListCheckboxItem
                key={option}
                value={option}
                checked={selected.includes(option)}
                onChange={() => toggle(option)}
              >
                {option}
              </DialogComboboxOptionListCheckboxItem>
            ))}
          </DialogComboboxOptionList>
        </DialogComboboxContent>
      </DialogCombobox>
    );
  }

  const selectedValue = typeof value === 'string' ? value : undefined;

  return (
    <DialogCombobox componentId={componentId} label={label} value={selectedValue ? [selectedValue] : []}>
      <DialogComboboxTrigger allowClear={false} disabled={disabled} />
      <DialogComboboxContent>
        <DialogComboboxOptionList>
          {input.options.map((option) => (
            <DialogComboboxOptionListSelectItem
              key={option}
              value={option}
              checked={selectedValue === option}
              onChange={() => onChange(option)}
            >
              {option}
            </DialogComboboxOptionListSelectItem>
          ))}
        </DialogComboboxOptionList>
      </DialogComboboxContent>
    </DialogCombobox>
  );
};
