import { Alert, Input } from '@databricks/design-system';
import type { LabelSchemaInput } from '../types';
import { LabelSchemaInputPassFail } from './LabelSchemaInputPassFail';
import { LabelSchemaInputNumeric } from './LabelSchemaInputNumeric';
import { LabelSchemaInputCategorical } from './LabelSchemaInputCategorical';

export interface LabelSchemaInputRendererProps {
  input: LabelSchemaInput;
  value: any;
  onChange: (value: any) => void;
  componentId: string;
  label?: string;
  disabled?: boolean;
  instruction?: string;
}

/**
 * Dispatches to the appropriate label schema input widget based on which
 * variant is set on the `input` object. Renders an error when the input does
 * not match any recognized variant.
 */
export const LabelSchemaInputRenderer = ({
  input,
  value,
  onChange,
  componentId,
  label,
  disabled,
}: LabelSchemaInputRendererProps) => {
  if (input.pass_fail) {
    return (
      <LabelSchemaInputPassFail
        input={input.pass_fail}
        value={value}
        onChange={onChange}
        componentId={componentId}
        disabled={disabled}
      />
    );
  }

  if (input.numeric) {
    return (
      <LabelSchemaInputNumeric
        input={input.numeric}
        value={value}
        onChange={onChange}
        componentId={componentId}
        disabled={disabled}
      />
    );
  }

  if (input.categorical) {
    return (
      <LabelSchemaInputCategorical
        input={input.categorical}
        value={value}
        onChange={onChange}
        componentId={componentId}
        label={label ?? ''}
        disabled={disabled}
      />
    );
  }

  if (input.text) {
    return (
      <Input
        componentId={componentId}
        value={value ?? ''}
        disabled={disabled}
        onChange={(event) => onChange(event.target.value)}
      />
    );
  }

  return (
    <Alert
      componentId={`${componentId}.error`}
      type="error"
      closable={false}
      message={
        <FormattedMessage
          defaultMessage="Invalid label schema"
          description="Error shown when a label schema has an unrecognized input variant"
        />
      }
    />
  );
};
